{"nbformat":4,"nbformat_minor":0,"metadata":{"colab":{"provenance":[{"file_id":"1kBe4oH6H-ki5oNdyXxRZvopRFJTu77u_","timestamp":1786783370666},{"file_id":"18QUdKVA9Ww6IMMoRMlEtVV029uAX5AZ_","timestamp":1769713229256},{"file_id":"10xZL2uaGZdACVahxQw0ODrn5isZUE-im","timestamp":1755268773180}]},"kernelspec":{"name":"python3","display_name":"Python 3"},"language_info":{"name":"python"}},"cells":[{"cell_type":"markdown","source":["**Consider the elliptic curve E: 𝑦2  = 𝑥3 − 2𝑥 + 2 (mod 23) and P = (4, 9)**\n","\n","1. Calculate the value of 2P and 3P.\n","\n","2. Suppose this E and P = (4, 9) are used in an ECC Diffie-Hellman key exchange, where Alice chooses the secret value a = 3 and Bob chooses the secret value b = 6. What is the shared key among Alice and Bob?"],"metadata":{"id":"IkBXA1KRJfjd"}},{"cell_type":"code","source":["# Elliptic curve: y^2 = x^3 - 2x + 2 (mod 23)\n","p = 23\n","a = -2\n","b = 2\n","P = (4, 9)"],"metadata":{"id":"YsOJ4sCQJVKa","collapsed":true,"executionInfo":{"status":"ok","timestamp":1786787158732,"user_tz":-360,"elapsed":10,"user":{"displayName":"AVINABO TARAFDER","userId":"16007127179575797832"}}},"execution_count":45,"outputs":[]},{"cell_type":"code","source":["def inverse_mod(k, p):\n","    return pow(k, -1, p)    # k-1 mod p"],"metadata":{"id":"kYpQa--9NEOe","executionInfo":{"status":"ok","timestamp":1786787158789,"user_tz":-360,"elapsed":22,"user":{"displayName":"AVINABO TARAFDER","userId":"16007127179575797832"}}},"execution_count":46,"outputs":[]},{"cell_type":"code","source":["#implement ECC point addition (also handle doubling)\n","def point_add(P, Q, a, p):\n","    #return Q if P is None, return P if Q is None\n","    #if P and Q are vertical reflections, return None\n","    #calculate slope m differently for doubling vs addition\n","    #compute x_r, y_r using ECC formulas, return as tuple\n","\n","    if P is None:\n","        return Q\n","    if Q is None:\n","        return P\n","    if P[1]==-Q[1]:\n","        return None\n","    if P!=Q:\n","        m = (Q[1]-P[1])%p * inverse_mod(Q[0]-P[0],p)\n","    if P==Q:\n","        m = (3*P[0]**2+a)%p * inverse_mod(2*P[1],p)\n","\n","    x_r = (m**2 - P[0] - Q[0]) %p\n","    y_r = (m*(P[0]-x_r) - P[1]) %p\n","    return (x_r, y_r)"],"metadata":{"id":"KSGSFuXLNLP7","executionInfo":{"status":"ok","timestamp":1786787158800,"user_tz":-360,"elapsed":29,"user":{"displayName":"AVINABO TARAFDER","userId":"16007127179575797832"}}},"execution_count":47,"outputs":[]},{"cell_type":"code","source":["#implement double-and-add scalar multiplication\n","def scalar_mult(k, P, a, p):\n","\n","    #start with R as None (point at infinity)\n","    #loop while k > 0, check k's binary bits\n","    #if bit is 1, add Q to R\n","    #always double Q each loop\n","    #shift k right each loop\n","\n","    R = None\n","    Q = P\n","    while k > 0:\n","        if k%2 == 1:\n","            R = point_add(R, Q, a, p)\n","        Q = point_add(Q, Q, a, p)\n","        k //= 2\n","\n","    return R\n","\n","# Note : function efficiently calculates k * P (scalar multiplication of point P by integer k) on an elliptic curve.\n","# It achieves this using the \"double-and-add\" algorithm.\n","# In each step, it either adds the current point Q to the running total R (if the current bit of k is 1) or doubles Q, then shifts k by one bit.\n","# This process quickly accumulates the sum k * P by leveraging point doubling and addition."],"metadata":{"id":"EMuB3OYmNLn8","executionInfo":{"status":"ok","timestamp":1786787158809,"user_tz":-360,"elapsed":27,"user":{"displayName":"AVINABO TARAFDER","userId":"16007127179575797832"}}},"execution_count":48,"outputs":[]},{"cell_type":"code","source":["# 1) 2P and 3P\n","P2 = scalar_mult(2, P, a, p)\n","P3 = scalar_mult(3, P, a, p)\n","print(\"2P =\", P2)\n","print(\"3P =\", P3)"],"metadata":{"id":"kzNk0JYfNMBN","colab":{"base_uri":"https://localhost:8080/"},"executionInfo":{"status":"ok","timestamp":1786787158821,"user_tz":-360,"elapsed":22,"user":{"displayName":"AVINABO TARAFDER","userId":"16007127179575797832"}},"outputId":"c465dadf-a56d-45fd-9f85-d34cd746fd8e"},"execution_count":49,"outputs":[{"output_type":"stream","name":"stdout","text":["2P = (15, 14)\n","3P = (12, 2)\n"]}]},{"cell_type":"code","source":["# 2) ECC Diffie–Hellman\n","a_secret = 3\n","b_secret = 6\n","\n","A_pub = scalar_mult(a_secret, P, a, p)\n","B_pub = scalar_mult(b_secret, P, a, p)\n","\n","shared_A = scalar_mult(a_secret, B_pub, a, p)\n","shared_B = scalar_mult(b_secret, A_pub, a, p)\n","\n","print(\"Alice's public key:\", A_pub)\n","print(\"Bob's public key:\", B_pub)\n","print(\"Shared key (Alice):\", shared_A)\n","print(\"Shared key (Bob):\", shared_B)"],"metadata":{"id":"avhktjins76Y","colab":{"base_uri":"https://localhost:8080/"},"executionInfo":{"status":"ok","timestamp":1786787158838,"user_tz":-360,"elapsed":15,"user":{"displayName":"AVINABO TARAFDER","userId":"16007127179575797832"}},"outputId":"87f615f1-1b41-4287-e236-471b807b7f2e"},"execution_count":50,"outputs":[{"output_type":"stream","name":"stdout","text":["Alice's public key: (12, 2)\n","Bob's public key: (15, 9)\n","Shared key (Alice): (15, 14)\n","Shared key (Bob): (15, 14)\n"]}]}]}